import {ToolRegistry} from './registry.js';

const WEATHER_SCHEMA = {
  type: 'object',
  properties: {location: {type: 'string'}},
  required: ['location'],
};

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {name: 'get_weather', description: 'Get weather for a location', inputSchema: WEATHER_SCHEMA},
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsRequiredField: true,
    });
  });

  it('rejects a wrong-typed field naming the path and expected type, without the offending value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']},
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect({
      executorCalls,
      mentionsFieldPath: response.result.includes('ssn'),
      mentionsExpectedType: response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
    }).toEqual({
      executorCalls: 0,
      mentionsFieldPath: true,
      mentionsExpectedType: true,
      leaksValue: false,
    });
  });

  it('passes valid input through to the executor unchanged, extra properties included, exactly once', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'echo',
        description: 'Echo its input back',
        inputSchema: {type: 'object', properties: {query: {type: 'string'}}, required: ['query']},
      },
      async input => {
        executorInputs.push(input);
        return 'ok';
      }
    );

    const response = await registry.execute('echo', {query: 'hello', extra: 'unlisted'});

    expect({
      calls: executorInputs.length,
      received: executorInputs[0],
      result: response.result,
    }).toEqual({
      calls: 1,
      received: {query: 'hello', extra: 'unlisted'},
      result: 'ok',
    });
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('ghost', {})).rejects.toThrow('Unknown tool: ghost');
  });

  it('validates a function-valued source against the schema current at each call', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    const strictSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
    const looseSchema = {type: 'object', properties: {location: {type: 'string'}}, required: []};
    let resolves = 0;
    registry.register(
      () => {
        resolves += 1;
        return {
          name: 'dynamic_weather',
          description: 'Get weather for a location',
          inputSchema: resolves === 1 ? looseSchema : strictSchema,
        };
      },
      async input => {
        executorCalls += 1;
        return `22C in ${String(input.location)}`;
      }
    );

    const rejected = await registry.execute('dynamic_weather', {});
    const accepted = await registry.execute('dynamic_weather', {location: 'Paris'});

    expect({
      rejectedForLocation: rejected.result.includes('location') && /required/i.test(rejected.result),
      executorCalls,
      acceptedResult: accepted.result,
    }).toEqual({
      rejectedForLocation: true,
      executorCalls: 1,
      acceptedResult: '22C in Paris',
    });
  });

  it('reuses the schema compiled at register time across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {name: 'static_weather', description: 'Get weather for a location', inputSchema: WEATHER_SCHEMA},
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );
    const definition = registry.getDefinitions()[0];
    definition.inputSchema.required = [];

    const results: string[] = [];
    for (let call = 0; call < 10; call += 1) {
      results.push((await registry.execute('static_weather', {})).result);
    }

    expect({
      executorCalls,
      allTenRejectedForLocation: results.every(
        result => result.includes('location') && /required/i.test(result)
      ),
    }).toEqual({
      executorCalls: 0,
      allTenRejectedForLocation: true,
    });
  });
});

